  host.innerHTML=rows.map(v=>"<tr><td>"+esc(v.siteId||"—")+"</td><td>"+esc(v.siteNo||"—")+"</td><td>"+esc(fmt(v.checkInAt))+"</td><td>"+esc(v.checkOutAt?fmt(v.checkOutAt):"Henüz çıkış yok")+"</td><td>"+esc(duration(v))+"</td><td>"+esc(v.visitReason||"—")+"</td><td>"+esc(v.workNotes||"—")+"</td></tr>").join("")||"<tr><td colspan=\"7\">Henüz saha ziyareti kaydın yok.</td></tr>";
