 function renderSiteIdSuggestions(){const box=$("siteIdSuggestions");if(!box)return;const prefix=normalizeId($("entrySiteCode").value);if(prefix.length<3){box.innerHTML="";box.classList.add("hidden");return}const matches=Object.values(sites).filter(s=>normalizeId(s.siteId||s.siteCode).startsWith(prefix)).sort((a,b)=>normalizeId(a.siteId||a.siteCode).localeCompare(normalizeId(b.siteId||b.siteCode))).slice(0,6);box.innerHTML=matches.map(s=>'<button type="button" class="site-id-suggestion" role="option" data-pick-site-id="'+esc(normalizeId(s.siteId||s.siteCode))+'"><span class="site-id-suggestion-main"><strong>'+esc(normalizeId(s.siteId||s.siteCode))+'</strong><small>'+esc(s.siteNo?"Saha No "+s.siteNo:"Saha No belirtilmemiş")+' · '+esc(s.company||"Firma belirtilmemiş")+'</small></span><span class="site-id-suggestion-status '+(s.approved===true?"approved":"pending")+'">'+esc(siteStatus(s))+'</span></button>').join("");if(!matches.length)box.innerHTML='<div class="site-id-suggestion-empty">“'+esc(prefix)+'” ile başlayan kayıt bulunamadı. Saha ID’ni yazmaya devam edebilirsin.</div>';box.classList.remove("hidden");}
