 function pendingVisitWriteKey(uid=auth.currentUser?.uid){return uid?"gsm-mobile-pending-visit-note:"+uid:""}
 function storePendingVisitNotes(workNotes,outcome){const key=pendingVisitWriteKey(),record=openVisitRecord;if(!key||!record?.siteRecordId||!Number(record.checkInAt))return false;try{const old=localStorage.getItem(key),existing=old?JSON.parse(old):null;if(existing&&(existing.siteRecordId!==record.siteRecordId||Number(existing.checkInAt)!==Number(record.checkInAt)))return false;localStorage.setItem(key,JSON.stringify({uid:auth.currentUser.uid,siteRecordId:record.siteRecordId,checkInAt:Number(record.checkInAt),workNotes:String(workNotes||"").trim(),outcome:String(outcome||""),queuedAt:Number(existing?.queuedAt)||Date.now(),updatedAt:Date.now()}));return true}catch(_){return false}}
 function persistVisitDraft(){const key=visitDraftStorageKey();if(!key)return;try{const draft={workNotes:$("visitWorkNotes").value,outcome:$("visitOutcome").value,updatedAt:Date.now()};if(!draft.workNotes&&!draft.outcome)sessionStorage.removeItem(key);else sessionStorage.setItem(key,JSON.stringify(draft));const pendingKey=pendingVisitWriteKey(),raw=localStorage.getItem(pendingKey);if(raw&&(draft.workNotes||draft.outcome)){const pending=JSON.parse(raw);localStorage.setItem(pendingKey,JSON.stringify({...pending,workNotes:draft.workNotes,outcome:draft.outcome,updatedAt:draft.updatedAt}))}}catch(_){}}
 function restoreVisitDraft(record){const pendingKey=pendingVisitWriteKey();try{const rawPending=localStorage.getItem(pendingKey);if(rawPending){const pending=JSON.parse(rawPending);if(pending.uid===auth.currentUser?.uid&&(pending.siteRecordId!==record.siteRecordId||Number(pending.checkInAt)!==Number(record.checkInAt))){msg("visitNotesMessage","Önceki ziyaretten gönderilemeyen notlar var. Bu kayıt korunuyor; yeni ziyaretin üzerine yazılmadı.","error")}else if(pending.uid===auth.currentUser?.uid&&Number(pending.updatedAt||pending.queuedAt)>Number(record.notesUpdatedAt||record.checkInAt||0)){$("visitWorkNotes").value=String(pending.workNotes||"");$("visitOutcome").value=String(pending.outcome||"");msg("visitNotesMessage","Bağlantı bekleyen notlar cihazda saklandı; internet/Firebase bağlantısı gelince otomatik gönderilecek.","");return}}}catch(_){}const key=visitDraftStorageKey();if(!key)return;try{const raw=sessionStorage.getItem(key);if(!raw)return;const draft=JSON.parse(raw);if(!draft||Number(draft.updatedAt||0)<=Number(record.notesUpdatedAt||record.checkInAt||0)){sessionStorage.removeItem(key);return}$("visitWorkNotes").value=String(draft.workNotes||"");$("visitOutcome").value=String(draft.outcome||"");msg("visitNotesMessage","Kaydedilmemiş taslak geri yüklendi. Sunucuya kaydetmek için “Notları kaydet” düğmesine bas.","");}catch(_){}}
 let pendingVisitSyncInFlight=false;
 async function syncPendingVisitNotes(){if(pendingVisitSyncInFlight||!navigator.onLine||!firebaseConnected||!auth.currentUser)return;const uid=auth.currentUser.uid,key=pendingVisitWriteKey(uid);let pending;try{const raw=localStorage.getItem(key);if(!raw)return;pending=JSON.parse(raw);if(!pending||pending.uid!==uid||!pending.siteRecordId||!Number(pending.checkInAt))return}catch(_){return}pendingVisitSyncInFlight=true;try{const ref=db.ref("openVisits/"+uid),snap=await ref.once("value"),visit=snap.val();if(!visit||visit.siteRecordId!==pending.siteRecordId||Number(visit.checkInAt)!==Number(pending.checkInAt)){msg("visitNotesMessage","Bekleyen notlar açık ziyaretle eşleşmedi. Veri cihazda korundu; yeni ziyaretin üzerine yazılmadı.","error");return}const latestRaw=localStorage.getItem(key);if(latestRaw)pending=JSON.parse(latestRaw);const workNotes=String(pending.workNotes||"").trim(),outcome=String(pending.outcome||"");if(!workNotes||!outcome){msg("visitNotesMessage","Bekleyen notlar eksik. Bağlantı kurulduğunda otomatik kaydetmek için işlem ve sonucu tamamlayın.","error");return}const updates={workNotes,outcome,notesUpdatedAt:Date.now()};await ref.update(updates);const afterRaw=localStorage.getItem(key);let hasNewer=false;if(afterRaw){try{hasNewer=JSON.stringify(JSON.parse(afterRaw))!==JSON.stringify(pending)}catch(_){hasNewer=true}}if(!hasNewer){localStorage.removeItem(key);clearVisitDraft()}openVisitRecord={...visit,...updates};if(activeSite?.id===visit.siteRecordId){$("visitWorkNotes").value=workNotes;$("visitOutcome").value=outcome}msg("visitNotesMessage",hasNewer?"Notlar senkronize edildi; daha yeni düzenlemeler sırada ve yeniden gönderilecek.":"Bekleyen saha notları internet bağlantısı gelince başarıyla senkronize edildi.","success");if(hasNewer)window.setTimeout(syncPendingVisitNotes,500)}catch(err){msg("visitNotesMessage","Bekleyen notlar henüz gönderilemedi; cihazda korundu. Bağlantı düzelince yeniden denenecek. "+(err.message||""),"error")}finally{pendingVisitSyncInFlight=false}}
