 $("contactMessageForm")?.addEventListener("submit",async e=>{e.preventDefault();const user=auth.currentUser,category=$("contactCategory").value,message=$("contactMessageText").value.trim(),button=$("sendContactMessageBtn");if(!user||!profile){msg("contactMessageFeedback","Oturum bilgisi bulunamadı. Lütfen yeniden giriş yapın.","error");return}if(!category||!message){msg("contactMessageFeedback","Konu ve mesaj alanlarını doldurun.","error");return}if(message.length>2000){msg("contactMessageFeedback","Mesaj en fazla 2.000 karakter olabilir.","error");return}if(!navigator.onLine||!firebaseConnected){msg("contactMessageFeedback","İnternet bağlantısı yok. Bağlantı sağlandığında tekrar deneyin.","error");return}button.disabled=true;const oldText=button.textContent;button.textContent="Gönderiliyor…";try{const accessSnap=await db.ref("access/"+user.uid).once("value");if(accessSnap.val()?.active!==true)throw new Error("Aktif personel erişimi bulunamadı.");const payload={ownerUid:user.uid,ownerName:String(profile.name||profile.username||"Personel").slice(0,80),ownerUsername:String(profile.username||"").slice(0,20),ownerCompany:String(profile.company||"").slice(0,100),category,message,createdAt:Date.now(),status:"new"};await db.ref("contactMessages").push(payload);msg("contactMessageFeedback","Mesajın yöneticiye iletildi. Teşekkürler.","success");$("contactMessageForm").reset()}catch(err){console.error("İletişim mesajı gönderilemedi:",err);msg("contactMessageFeedback","Mesaj gönderilemedi: "+(err.code==="PERMISSION_DENIED"?"Firebase güvenlik kuralları bu işlemi reddetti. Yönetici, database.rules.json kurallarını yayımlamalı.":(err.message||"Bilinmeyen hata")),"error")}finally{button.disabled=false;button.textContent=oldText}});
