 $("profileChangeForm").addEventListener("submit",async e=>{e.preventDefault();const changes={email:$("editProfileEmail").value.trim(),company:$("editProfileCompany").value.trim(),phone:$("editProfilePhone").value.trim()};if(!changes.email||!changes.company||!changes.phone){msg("profileChangeMessage","E-posta, firma ve telefon alanlarının tümü doldurulmalı.","error");return}try{const snap=await db.ref("profileChangeRequests").orderByChild("ownerUid").equalTo(auth.currentUser.uid).once("value");const pending=Object.values(snap.val()||{}).some(x=>x.status==="pending");if(pending){msg("profileChangeMessage","Zaten yönetici onayı bekleyen bir profil değişikliği var.","error");return}const ref=db.ref("profileChangeRequests").push();await ref.set({id:ref.key,ownerUid:auth.currentUser.uid,ownerName:profile.name||"",current:{email:profile.email||"",company:profile.company||"",phone:profile.phone||""},requested:changes,status:"pending",createdAt:Date.now()});await db.ref("adminInbox").push({type:"profile-change",ownerUid:auth.currentUser.uid,ownerName:profile.name||"",title:"Profil değişikliği talebi",detail:changes.email+" · "+changes.company+" · "+changes.phone,createdAt:Date.now(),read:false});msg("profileChangeMessage","Değişiklik talebin yönetici onayına gönderildi.","success");$("profilePendingMessage").textContent="Profil değişikliği: yönetici onayı bekliyor.";hide("profilePendingMessage",false)}catch(err){msg("profileChangeMessage","Talep gönderilemedi: "+err.message,"error")}});
