 $("exportSitesCsv").addEventListener("click",()=>{const visits=Object.values(visitHistoryData||{}).filter(v=>auth.currentUser&&v.uid===auth.currentUser.uid);if(openVisitRecord&&auth.currentUser&&openVisitRecord.uid===auth.currentUser.uid&&!visits.some(v=>Number(v.checkInAt)===Number(openVisitRecord.checkInAt)))visits.push(openVisitRecord);const rows=[["Saha ID","Saha No","Giriş zamanı","Çıkış zamanı","Süre (dk)","Giriş nedeni","Yapılan işlem","Sonuç"],...visits.map(v=>[v.siteId,v.siteNo,v.checkInAt?new Date(v.checkInAt).toLocaleString("tr-TR"):"",v.checkOutAt?new Date(v.checkOutAt).toLocaleString("tr-TR"):"Devam ediyor",Math.max(0,Math.floor(((Number(v.checkOutAt)||Date.now())-(Number(v.checkInAt)||Date.now()))/60000)),v.visitReason,v.workNotes,v.outcome])];const csv="\uFEFF"+rows.map(r=>r.map(v=>"\""+String(v??"").replace(/"/g,"\"\"")+"\"").join(";")).join("\r\n");const a=document.createElement("a"),url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));a.href=url;a.download="gsm-kisisel-saha-raporlarim.csv";a.click();URL.revokeObjectURL(url)});
